const HTML_CONTENT = "<!DOCTYPE html>\n<html lang=\"zh-CN\" data-theme=\"dark\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, viewport-fit=cover\">\n  <title>高考全科知识库 · 高中理科系统级知识中枢</title>\n  <meta name=\"description\" content=\"面向新高考深度备考的高中理科系统知识中枢。以第一性原理重构物理、生物、化学核心公理推演、临界模型与全景知识图谱。\">\n  <meta name=\"keywords\" content=\"高考知识库,高中物理,高中生物,高中化学,第一性原理,知识图谱,高考理科\">\n  <meta name=\"author\" content=\"Yulaoshizuikeai\">\n  \n  <!-- OpenGraph / Social Cards -->\n  <meta property=\"og:type\" content=\"website\">\n  <meta property=\"og:url\" content=\"https://note.yunet.cfd/\">\n  <meta property=\"og:title\" content=\"高考全科知识库 · 高中理科系统级知识中枢\">\n  <meta property=\"og:description\" content=\"以第一性原理重构高考理科体系。涵盖物理经典专题模型推导、生物全册机制通路与化学微观反应平衡。\">\n  <meta property=\"og:image\" content=\"https://note.yunet.cfd/images/icon.svg\">\n  <meta name=\"twitter:card\" content=\"summary_large_image\">\n  \n  <!-- Favicon -->\n  <link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\">\n  <link rel=\"apple-touch-icon\" href=\"/images/icon.svg\">\n\n  <!-- Google Fonts: Plus Jakarta Sans (Elite Grotesk for Latin/Numbers) -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n\n  <style>\n    /* ==========================================================================\n       1. SYSTEM COLOR DESIGN TOKENS & HAPTIC SYSTEM\n       ========================================================================== */\n    :root {\n      /* Base Theme: Light Mode (Porous Soft Structuralism) */\n      --bg-canvas: #fbfbfd;\n      --bg-surface: #ffffff;\n      --bg-surface-elevated: #f4f4f7;\n      --bg-glass: rgba(255, 255, 255, 0.78);\n      --bg-glass-border: rgba(0, 0, 0, 0.08);\n\n      --bezel-outer-bg: rgba(0, 0, 0, 0.025);\n      --bezel-outer-border: rgba(0, 0, 0, 0.07);\n      --bezel-inner-border: rgba(0, 0, 0, 0.05);\n      --bezel-inner-highlight: inset 0 1px 1px rgba(255, 255, 255, 0.95);\n      --bezel-shadow: 0 16px 40px -12px rgba(17, 24, 39, 0.07), 0 2px 6px -1px rgba(17, 24, 39, 0.03);\n\n      --text-primary: #0f1015;\n      --text-secondary: #4a4d57;\n      --text-tertiary: #7e8392;\n      --text-faint: #a6abb9;\n\n      --badge-bg: rgba(0, 0, 0, 0.04);\n      --badge-border: rgba(0, 0, 0, 0.08);\n      --badge-text: #27272a;\n\n      /* Subject Signatures */\n      --phy-accent: #ea580c;\n      --phy-gradient: linear-gradient(135deg, #f97316 0%, #ea580c 60%, #c2410c 100%);\n      --phy-glow: rgba(234, 88, 12, 0.12);\n\n      --bio-accent: #059669;\n      --bio-gradient: linear-gradient(135deg, #10b981 0%, #059669 60%, #047857 100%);\n      --bio-glow: rgba(5, 150, 105, 0.12);\n\n      --chem-accent: #0284c7;\n      --chem-gradient: linear-gradient(135deg, #38bdf8 0%, #0284c7 60%, #0369a1 100%);\n      --chem-glow: rgba(2, 132, 199, 0.12);\n\n      --font-display: \"Plus Jakarta Sans\", -apple-system, BlinkMacSystemFont, \"SF Pro Display\", \"PingFang SC\", \"Hiragino Sans GB\", sans-serif;\n      --font-mono: ui-monospace, \"SF Mono\", Menlo, Consolas, monospace;\n\n      --ease-spring: cubic-bezier(0.16, 1, 0.3, 1);\n      --ease-flow: cubic-bezier(0.32, 0.72, 0, 1);\n    }\n\n    [data-theme=\"dark\"] {\n      /* Dark Mode: Ethereal Vantablack Glass */\n      --bg-canvas: #050507;\n      --bg-surface: #0c0c10;\n      --bg-surface-elevated: #14141a;\n      --bg-glass: rgba(12, 12, 16, 0.78);\n      --bg-glass-border: rgba(255, 255, 255, 0.09);\n\n      --bezel-outer-bg: rgba(255, 255, 255, 0.03);\n      --bezel-outer-border: rgba(255, 255, 255, 0.08);\n      --bezel-inner-border: rgba(255, 255, 255, 0.06);\n      --bezel-inner-highlight: inset 0 1px 1px rgba(255, 255, 255, 0.13);\n      --bezel-shadow: 0 20px 48px -16px rgba(0, 0, 0, 0.7), 0 2px 8px -2px rgba(0, 0, 0, 0.5);\n\n      --text-primary: #fbfbfd;\n      --text-secondary: #9ea2b0;\n      --text-tertiary: #676a77;\n      --text-faint: #42444e;\n\n      --badge-bg: rgba(255, 255, 255, 0.05);\n      --badge-border: rgba(255, 255, 255, 0.1);\n      --badge-text: #e4e4e7;\n\n      --phy-accent: #fb923c;\n      --phy-gradient: linear-gradient(135deg, #fdba74 0%, #f97316 60%, #ea580c 100%);\n      --phy-glow: rgba(249, 115, 22, 0.18);\n\n      --bio-accent: #34d399;\n      --bio-gradient: linear-gradient(135deg, #6ee7b7 0%, #10b981 60%, #059669 100%);\n      --bio-glow: rgba(16, 185, 129, 0.18);\n\n      --chem-accent: #38bdf8;\n      --chem-gradient: linear-gradient(135deg, #7dd3fc 0%, #38bdf8 60%, #0284c7 100%);\n      --chem-glow: rgba(56, 189, 248, 0.18);\n    }\n\n    /* ==========================================================================\n       2. RESET & FOUNDATIONAL SCAFFOLD\n       ========================================================================== */\n    *, *::before, *::after {\n      box-sizing: border-box;\n      margin: 0;\n      padding: 0;\n      -webkit-font-smoothing: antialiased;\n      -moz-osx-font-smoothing: grayscale;\n    }\n\n    html {\n      font-size: 16px;\n      scroll-behavior: smooth;\n    }\n\n    body {\n      background-color: var(--bg-canvas);\n      color: var(--text-primary);\n      font-family: var(--font-display);\n      min-height: 100dvh;\n      line-height: 1.65;\n      letter-spacing: -0.015em;\n      position: relative;\n      overflow-x: hidden;\n      transition: background-color 0.6s var(--ease-spring), color 0.6s var(--ease-spring);\n    }\n\n    /* Film Grain Noise Overlay (Strict Performance: Fixed & pointer-events: none) */\n    .noise-overlay {\n      position: fixed;\n      inset: 0;\n      width: 100vw;\n      height: 100vh;\n      pointer-events: none !important;\n      z-index: 1;\n      opacity: 0.022;\n      background-image: url(\"data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E\");\n    }\n\n    /* Radial Ambient Background Glows */\n    .ambient-glows {\n      position: absolute;\n      inset: 0;\n      pointer-events: none !important;\n      overflow: hidden;\n      z-index: 0;\n    }\n\n    .glow-orb {\n      position: absolute;\n      border-radius: 50%;\n      filter: blur(140px);\n      opacity: 0.45;\n      transform: translateZ(0);\n      will-change: transform;\n      pointer-events: none !important;\n    }\n\n    .glow-orb-1 {\n      top: -100px;\n      left: 50%;\n      transform: translateX(-50%);\n      width: 850px;\n      height: 480px;\n      background: radial-gradient(circle, rgba(234, 88, 12, 0.14) 0%, rgba(16, 185, 129, 0.08) 45%, rgba(2, 132, 199, 0.03) 80%, transparent 100%);\n    }\n\n    .glow-orb-2 {\n      top: 900px;\n      right: -100px;\n      width: 600px;\n      height: 600px;\n      background: radial-gradient(circle, rgba(2, 132, 199, 0.1) 0%, rgba(234, 88, 12, 0.03) 70%, transparent 100%);\n    }\n\n    .main-wrapper {\n      position: relative;\n      z-index: 10;\n      max-width: 1140px;\n      margin: 0 auto;\n      padding: 0 24px;\n    }\n\n    /* ==========================================================================\n       3. FLUID ISLAND DETACHED NAV\n       ========================================================================== */\n    .nav-container {\n      position: sticky;\n      top: 24px;\n      z-index: 100;\n      display: flex;\n      justify-content: center;\n      padding: 0 16px;\n    }\n\n    .fluid-island-nav {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 28px;\n      padding: 8px 12px 8px 18px;\n      border-radius: 9999px;\n      background: var(--bg-glass);\n      backdrop-filter: blur(24px);\n      -webkit-backdrop-filter: blur(24px);\n      border: 1px solid var(--bg-glass-border);\n      box-shadow: 0 12px 32px -8px rgba(0, 0, 0, 0.18), inset 0 1px 1px rgba(255, 255, 255, 0.12);\n      transition: all 0.5s var(--ease-spring);\n    }\n\n    .nav-brand {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n      text-decoration: none;\n      color: inherit;\n    }\n\n    .brand-mark {\n      width: 32px;\n      height: 32px;\n      border-radius: 50%;\n      background: var(--text-primary);\n      color: var(--bg-canvas);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      font-size: 14px;\n      font-weight: 800;\n      letter-spacing: -0.05em;\n      box-shadow: 0 2px 8px rgba(0, 0, 0, 0.2);\n    }\n\n    .brand-title {\n      font-size: 13.5px;\n      font-weight: 700;\n      letter-spacing: -0.02em;\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n\n    .status-badge {\n      display: inline-flex;\n      align-items: center;\n      gap: 6px;\n      padding: 3px 9px;\n      border-radius: 9999px;\n      background: rgba(16, 185, 129, 0.1);\n      border: 1px solid rgba(16, 185, 129, 0.22);\n      font-size: 10px;\n      font-family: var(--font-mono);\n      font-weight: 600;\n      color: #10b981;\n      letter-spacing: 0.06em;\n      text-transform: uppercase;\n    }\n\n    .status-pulse {\n      width: 5px;\n      height: 5px;\n      border-radius: 50%;\n      background-color: #10b981;\n      box-shadow: 0 0 8px #10b981;\n      animation: pulse-dot 2.4s infinite var(--ease-flow);\n    }\n\n    @keyframes pulse-dot {\n      0%, 100% { opacity: 1; transform: scale(1); }\n      50% { opacity: 0.4; transform: scale(0.85); }\n    }\n\n    .nav-links {\n      display: flex;\n      align-items: center;\n      gap: 6px;\n    }\n\n    .nav-link {\n      padding: 6px 14px;\n      border-radius: 9999px;\n      font-size: 12.5px;\n      font-weight: 500;\n      color: var(--text-secondary);\n      text-decoration: none;\n      transition: all 0.3s var(--ease-spring);\n    }\n\n    .nav-link:hover {\n      color: var(--text-primary);\n      background: rgba(255, 255, 255, 0.08);\n    }\n\n    .nav-actions {\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n\n    .theme-button {\n      position: relative;\n      width: 36px;\n      height: 36px;\n      border-radius: 50%;\n      border: 1px solid var(--bezel-inner-border);\n      background: var(--bg-surface-elevated);\n      color: var(--text-secondary);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      cursor: pointer;\n      outline: none;\n      transition: all 0.4s var(--ease-spring);\n    }\n\n    .theme-button:hover {\n      color: var(--text-primary);\n      transform: scale(1.05);\n      border-color: var(--bezel-outer-border);\n    }\n\n    .theme-button svg {\n      width: 16px;\n      height: 16px;\n      stroke-width: 1.5;\n      stroke: currentColor;\n      fill: none;\n      transition: transform 0.5s var(--ease-spring);\n    }\n\n    /* ==========================================================================\n       4. HERO SECTION (MACRO-WHITESPACE & EDITORIAL SCALE)\n       ========================================================================= */\n    .hero-section {\n      padding: 110px 0 80px;\n      text-align: center;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      position: relative;\n    }\n\n    .eyebrow-tag {\n      display: inline-flex;\n      align-items: center;\n      gap: 8px;\n      padding: 6px 16px;\n      border-radius: 9999px;\n      background: var(--badge-bg);\n      border: 1px solid var(--badge-border);\n      font-size: 11px;\n      font-weight: 600;\n      letter-spacing: 0.18em;\n      text-transform: uppercase;\n      color: var(--badge-text);\n      margin-bottom: 28px;\n      backdrop-filter: blur(8px);\n    }\n\n    .eyebrow-indicator {\n      width: 6px;\n      height: 6px;\n      border-radius: 50%;\n      background: var(--phy-accent);\n      box-shadow: 0 0 10px var(--phy-accent);\n    }\n\n    .hero-title {\n      font-size: clamp(38px, 6.2vw, 68px);\n      font-weight: 800;\n      line-height: 1.14;\n      letter-spacing: -0.04em;\n      max-width: 880px;\n      margin-bottom: 24px;\n      color: var(--text-primary);\n    }\n\n    .hero-title .shimmer-text {\n      background: linear-gradient(135deg, var(--text-primary) 20%, var(--text-tertiary) 100%);\n      -webkit-background-clip: text;\n      -webkit-text-fill-color: transparent;\n    }\n\n    .hero-subtitle {\n      font-size: clamp(15.5px, 1.8vw, 18.5px);\n      color: var(--text-secondary);\n      max-width: 660px;\n      line-height: 1.7;\n      margin-bottom: 44px;\n      font-weight: 400;\n    }\n\n    /* Nested Island CTA & Button Architecture */\n    .hero-cta-group {\n      display: flex;\n      align-items: center;\n      gap: 16px;\n      flex-wrap: wrap;\n      justify-content: center;\n      margin-bottom: 64px;\n    }\n\n    .island-btn {\n      display: inline-flex;\n      align-items: center;\n      gap: 14px;\n      padding: 6px 8px 6px 24px;\n      border-radius: 9999px;\n      font-size: 14.5px;\n      font-weight: 600;\n      text-decoration: none;\n      cursor: pointer;\n      position: relative;\n      transition: all 0.5s var(--ease-spring);\n      outline: none;\n    }\n\n    .island-btn:active {\n      transform: scale(0.97);\n    }\n\n    .island-btn-primary {\n      background: var(--text-primary);\n      color: var(--bg-canvas);\n      box-shadow: 0 8px 24px -4px rgba(0, 0, 0, 0.25);\n    }\n\n    .island-btn-primary:hover {\n      box-shadow: 0 14px 32px -4px rgba(0, 0, 0, 0.35);\n      transform: translateY(-2px);\n    }\n\n    .island-btn-secondary {\n      background: var(--bg-surface-elevated);\n      color: var(--text-primary);\n      border: 1px solid var(--bezel-outer-border);\n    }\n\n    .island-btn-secondary:hover {\n      background: var(--bg-surface);\n      border-color: var(--text-tertiary);\n      transform: translateY(-2px);\n    }\n\n    /* Button-in-Button Trailing Icon Architecture */\n    .btn-icon-wrapper {\n      width: 36px;\n      height: 36px;\n      border-radius: 50%;\n      background: rgba(255, 255, 255, 0.15);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      flex-shrink: 0;\n      transition: transform 0.5s var(--ease-spring), background 0.3s var(--ease-spring);\n    }\n\n    .island-btn-secondary .btn-icon-wrapper {\n      background: rgba(0, 0, 0, 0.06);\n    }\n\n    [data-theme=\"dark\"] .island-btn-secondary .btn-icon-wrapper {\n      background: rgba(255, 255, 255, 0.08);\n    }\n\n    .island-btn:hover .btn-icon-wrapper {\n      transform: translate(3px, -2px) scale(1.08);\n    }\n\n    .btn-icon-wrapper svg {\n      width: 14px;\n      height: 14px;\n      stroke-width: 2;\n      stroke: currentColor;\n      fill: none;\n    }\n\n    /* System Stats Ribbon */\n    .spec-strip {\n      display: grid;\n      grid-template-columns: repeat(4, 1fr);\n      gap: 16px;\n      width: 100%;\n      max-width: 960px;\n    }\n\n    .spec-item {\n      padding: 18px 20px;\n      border-radius: 20px;\n      background: var(--bg-surface);\n      border: 1px solid var(--bezel-outer-border);\n      text-align: left;\n      transition: all 0.4s var(--ease-spring);\n    }\n\n    .spec-item:hover {\n      border-color: var(--bezel-inner-border);\n      transform: translateY(-2px);\n      box-shadow: var(--bezel-shadow);\n    }\n\n    .spec-num {\n      font-size: 26px;\n      font-weight: 800;\n      letter-spacing: -0.03em;\n      line-height: 1.2;\n      color: var(--text-primary);\n      font-family: var(--font-display);\n    }\n\n    .spec-num span {\n      font-size: 18px;\n      color: var(--phy-accent);\n      margin-left: 2px;\n    }\n\n    .spec-label {\n      font-size: 12px;\n      color: var(--text-secondary);\n      margin-top: 4px;\n      font-weight: 500;\n    }\n\n    /* ==========================================================================\n       5. ASYMMETRICAL BENTO & DOUBLE-BEZEL (DOPPELRAND) ARCHITECTURE\n       ========================================================================== */\n    .section-container {\n      padding: 72px 0;\n    }\n\n    .section-header-pill {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      margin-bottom: 28px;\n      padding-bottom: 16px;\n      border-bottom: 1px solid var(--bezel-outer-border);\n    }\n\n    .section-title-label {\n      font-size: 12px;\n      font-weight: 700;\n      letter-spacing: 0.16em;\n      text-transform: uppercase;\n      font-family: var(--font-mono);\n      color: var(--text-tertiary);\n      display: flex;\n      align-items: center;\n      gap: 10px;\n    }\n\n    .section-title-label::before {\n      content: \"\";\n      display: inline-block;\n      width: 8px;\n      height: 8px;\n      border-radius: 2px;\n      background: var(--text-tertiary);\n    }\n\n    .section-aux-info {\n      font-size: 12px;\n      color: var(--text-faint);\n      font-family: var(--font-mono);\n    }\n\n    /* Bento Grid: 1 Large Asymmetric Anchor (Physics) + 2 Balanced Twins (Bio, Chem) */\n    .bento-grid {\n      display: grid;\n      grid-template-columns: repeat(12, 1fr);\n      gap: 20px;\n    }\n\n    /* Double-Bezel Card Master Formula */\n    .double-bezel {\n      border-radius: 2.25rem; /* Outer radius */\n      padding: 7px;\n      background: var(--bezel-outer-bg);\n      border: 1px solid var(--bezel-outer-border);\n      box-shadow: var(--bezel-shadow);\n      transition: transform 0.5s var(--ease-spring), border-color 0.5s var(--ease-spring), box-shadow 0.5s var(--ease-spring);\n      position: relative;\n      text-decoration: none;\n      color: inherit;\n      display: block;\n      cursor: pointer;\n    }\n\n    .double-bezel:hover {\n      transform: translateY(-4px);\n      border-color: var(--text-faint);\n    }\n\n    .inner-core {\n      border-radius: calc(2.25rem - 7px); /* Concentric inner radius */\n      background: var(--bg-surface);\n      border: 1px solid var(--bezel-inner-border);\n      box-shadow: var(--bezel-inner-highlight);\n      padding: 36px 38px;\n      height: 100%;\n      display: flex;\n      flex-direction: column;\n      justify-content: space-between;\n      position: relative;\n      overflow: hidden;\n    }\n\n    /* Physics Flagship: Spans 12 columns (Heroic Panorama) */\n    .bento-physics {\n      grid-column: span 12;\n    }\n\n    .bento-physics .inner-core {\n      background: radial-gradient(circle at 90% 10%, var(--phy-glow) 0%, var(--bg-surface) 65%);\n    }\n\n    /* Biology & Chemistry: 6 columns each */\n    .bento-bio {\n      grid-column: span 6;\n    }\n\n    .bento-bio .inner-core {\n      background: radial-gradient(circle at 90% 10%, var(--bio-glow) 0%, var(--bg-surface) 65%);\n    }\n\n    .bento-chem {\n      grid-column: span 6;\n    }\n\n    .bento-chem .inner-core {\n      background: radial-gradient(circle at 90% 10%, var(--chem-glow) 0%, var(--bg-surface) 65%);\n    }\n\n    /* Card Top Bar & Metadata */\n    .card-top {\n      display: flex;\n      align-items: flex-start;\n      justify-content: space-between;\n      margin-bottom: 24px;\n    }\n\n    .card-badge-row {\n      display: flex;\n      align-items: center;\n      gap: 10px;\n    }\n\n    .card-domain-badge {\n      font-size: 11px;\n      font-family: var(--font-mono);\n      font-weight: 600;\n      color: var(--text-tertiary);\n      letter-spacing: 0.04em;\n    }\n\n    .subject-pill-tag {\n      padding: 4px 10px;\n      border-radius: 9999px;\n      font-size: 11px;\n      font-weight: 700;\n      letter-spacing: 0.08em;\n      text-transform: uppercase;\n    }\n\n    .tag-phy {\n      background: rgba(234, 88, 12, 0.12);\n      color: var(--phy-accent);\n      border: 1px solid rgba(234, 88, 12, 0.25);\n    }\n\n    .tag-bio {\n      background: rgba(16, 185, 129, 0.12);\n      color: var(--bio-accent);\n      border: 1px solid rgba(16, 185, 129, 0.25);\n    }\n\n    .tag-chem {\n      background: rgba(56, 189, 248, 0.12);\n      color: var(--chem-accent);\n      border: 1px solid rgba(56, 189, 248, 0.25);\n    }\n\n    .subject-icon-box {\n      width: 44px;\n      height: 44px;\n      border-radius: 14px;\n      background: var(--bg-surface-elevated);\n      border: 1px solid var(--bezel-outer-border);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      color: var(--text-primary);\n      transition: all 0.5s var(--ease-spring);\n    }\n\n    .double-bezel:hover .subject-icon-box {\n      transform: scale(1.1) rotate(4deg);\n    }\n\n    .subject-icon-box svg {\n      width: 22px;\n      height: 22px;\n      stroke-width: 1.4;\n      stroke: currentColor;\n      fill: none;\n    }\n\n    /* Card Content */\n    .card-headline {\n      font-size: 26px;\n      font-weight: 700;\n      letter-spacing: -0.03em;\n      line-height: 1.25;\n      margin-bottom: 12px;\n      color: var(--text-primary);\n      display: flex;\n      align-items: center;\n      gap: 12px;\n    }\n\n    .card-desc {\n      font-size: 14.5px;\n      line-height: 1.7;\n      color: var(--text-secondary);\n      margin-bottom: 28px;\n      max-width: 640px;\n    }\n\n    .bento-physics .card-desc {\n      max-width: 720px;\n      font-size: 15.5px;\n    }\n\n    /* Micro Vector Graphics Accent within Card */\n    .card-vector-preview {\n      margin: 16px 0 28px;\n      padding: 16px 20px;\n      border-radius: 16px;\n      background: var(--bg-surface-elevated);\n      border: 1px solid var(--bezel-outer-border);\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 16px;\n    }\n\n    .vector-label {\n      font-size: 12.5px;\n      font-family: var(--font-mono);\n      color: var(--text-secondary);\n    }\n\n    .vector-pill-cluster {\n      display: flex;\n      gap: 8px;\n      flex-wrap: wrap;\n    }\n\n    .vector-pill {\n      font-size: 11px;\n      padding: 3px 9px;\n      border-radius: 6px;\n      background: var(--bg-surface);\n      border: 1px solid var(--bezel-inner-border);\n      color: var(--text-tertiary);\n      font-family: var(--font-mono);\n    }\n\n    /* Card Footer & Trailing Action */\n    .card-footer {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      padding-top: 20px;\n      border-top: 1px solid var(--bezel-outer-border);\n      margin-top: auto;\n    }\n\n    .card-tags {\n      display: flex;\n      gap: 8px;\n      flex-wrap: wrap;\n    }\n\n    .meta-tag {\n      font-size: 12px;\n      font-weight: 500;\n      color: var(--text-tertiary);\n      background: var(--badge-bg);\n      border: 1px solid var(--badge-border);\n      padding: 3px 10px;\n      border-radius: 9999px;\n    }\n\n    /* Nested Action Link */\n    .card-cta-link {\n      display: inline-flex;\n      align-items: center;\n      gap: 10px;\n      font-size: 13.5px;\n      font-weight: 600;\n      color: var(--text-primary);\n      text-decoration: none;\n      transition: all 0.4s var(--ease-spring);\n    }\n\n    .cta-circle {\n      width: 34px;\n      height: 34px;\n      border-radius: 50%;\n      background: var(--bg-surface-elevated);\n      border: 1px solid var(--bezel-outer-border);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      transition: all 0.5s var(--ease-spring);\n    }\n\n    .cta-circle svg {\n      width: 14px;\n      height: 14px;\n      stroke-width: 1.8;\n      stroke: currentColor;\n      fill: none;\n      transition: transform 0.4s var(--ease-spring);\n    }\n\n    .double-bezel:hover .cta-circle {\n      background: var(--text-primary);\n      color: var(--bg-canvas);\n      transform: translate(3px, -2px) scale(1.06);\n    }\n\n    .double-bezel:hover .cta-circle svg {\n      transform: translate(1px, -1px);\n    }\n\n    /* ==========================================================================\n       6. SYSTEM ARCHITECTURE METHODOLOGY (4 PILLARS)\n       ========================================================================== */\n    .pillars-grid {\n      display: grid;\n      grid-template-columns: repeat(4, 1fr);\n      gap: 16px;\n    }\n\n    .pillar-card {\n      border-radius: 1.75rem;\n      padding: 5px;\n      background: var(--bezel-outer-bg);\n      border: 1px solid var(--bezel-outer-border);\n      transition: transform 0.4s var(--ease-spring);\n    }\n\n    .pillar-card:hover {\n      transform: translateY(-3px);\n    }\n\n    .pillar-inner {\n      border-radius: calc(1.75rem - 5px);\n      background: var(--bg-surface);\n      border: 1px solid var(--bezel-inner-border);\n      box-shadow: var(--bezel-inner-highlight);\n      padding: 26px 22px;\n      height: 100%;\n      display: flex;\n      flex-direction: column;\n    }\n\n    .pillar-header {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      margin-bottom: 18px;\n    }\n\n    .pillar-number {\n      font-size: 13px;\n      font-family: var(--font-mono);\n      font-weight: 700;\n      color: var(--text-tertiary);\n    }\n\n    .pillar-icon-tiny {\n      width: 28px;\n      height: 28px;\n      border-radius: 8px;\n      background: var(--bg-surface-elevated);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      color: var(--text-secondary);\n    }\n\n    .pillar-icon-tiny svg {\n      width: 14px;\n      height: 14px;\n      stroke-width: 1.5;\n      stroke: currentColor;\n      fill: none;\n    }\n\n    .pillar-title {\n      font-size: 16px;\n      font-weight: 700;\n      letter-spacing: -0.02em;\n      color: var(--text-primary);\n      margin-bottom: 8px;\n    }\n\n    .pillar-desc {\n      font-size: 13px;\n      line-height: 1.65;\n      color: var(--text-secondary);\n    }\n\n    /* ==========================================================================\n       7. EDITORIAL FOOTER\n       ========================================================================== */\n    .site-footer {\n      padding: 80px 0 60px;\n      margin-top: 40px;\n      border-top: 1px solid var(--bezel-outer-border);\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      flex-wrap: wrap;\n      gap: 24px;\n    }\n\n    .footer-identity {\n      display: flex;\n      flex-direction: column;\n      gap: 6px;\n    }\n\n    .footer-brand {\n      font-size: 14px;\n      font-weight: 700;\n      color: var(--text-primary);\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n\n    .footer-copy {\n      font-size: 12px;\n      color: var(--text-tertiary);\n    }\n\n    .footer-nav {\n      display: flex;\n      align-items: center;\n      gap: 20px;\n      flex-wrap: wrap;\n    }\n\n    .footer-link {\n      font-size: 13px;\n      color: var(--text-secondary);\n      text-decoration: none;\n      transition: color 0.3s var(--ease-spring);\n    }\n\n    .footer-link:hover {\n      color: var(--text-primary);\n    }\n\n    /* ==========================================================================\n       8. SCROLL REVEAL ANIMATIONS (INTERSECTION OBSERVER FLUID DYNAMICS)\n       ========================================================================== */\n    .reveal-element {\n      opacity: 0;\n      transform: translateY(32px);\n      filter: blur(6px);\n      transition: opacity 0.85s var(--ease-flow), transform 0.85s var(--ease-flow), filter 0.85s var(--ease-flow);\n      will-change: opacity, transform, filter;\n    }\n\n    .reveal-element.is-revealed {\n      opacity: 1;\n      transform: translateY(0);\n      filter: blur(0);\n    }\n\n    /* ==========================================================================\n       9. RESPONSIVE MOBILE COLLAPSE (STRICT DIRECTIVES)\n       ========================================================================== */\n    @media (max-width: 960px) {\n      .pillars-grid {\n        grid-template-columns: repeat(2, 1fr);\n      }\n      .spec-strip {\n        grid-template-columns: repeat(2, 1fr);\n      }\n    }\n\n    @media (max-width: 768px) {\n      .main-wrapper {\n        padding: 0 16px;\n      }\n\n      .nav-container {\n        top: 16px;\n      }\n\n      .fluid-island-nav {\n        width: 100%;\n        max-width: 480px;\n        gap: 12px;\n        padding: 8px 12px;\n      }\n\n      .nav-links {\n        display: none; /* Collapses into focused minimal bar on mobile */\n      }\n\n      .hero-section {\n        padding: 70px 0 50px;\n      }\n\n      .hero-title {\n        font-size: 34px;\n      }\n\n      .hero-subtitle {\n        font-size: 15px;\n      }\n\n      .spec-strip {\n        grid-template-columns: 1fr;\n        gap: 10px;\n      }\n\n      .bento-grid {\n        display: flex;\n        flex-direction: column;\n        gap: 16px;\n      }\n\n      .bento-physics, .bento-bio, .bento-chem {\n        grid-column: span 12;\n      }\n\n      .inner-core {\n        padding: 26px 20px;\n      }\n\n      .pillars-grid {\n        grid-template-columns: 1fr;\n        gap: 12px;\n      }\n\n      .site-footer {\n        flex-direction: column;\n        align-items: flex-start;\n        padding: 50px 0 40px;\n      }\n    }\n  </style>\n</head>\n<body>\n\n  <!-- Physical Grain / Noise Texture Overlay -->\n  <div class=\"noise-overlay\" aria-hidden=\"true\"></div>\n\n  <!-- Ambient Light Orbs -->\n  <div class=\"ambient-glows\" aria-hidden=\"true\">\n    <div class=\"glow-orb glow-orb-1\"></div>\n    <div class=\"glow-orb glow-orb-2\"></div>\n  </div>\n\n  <!-- Main Viewport Flow -->\n  <div class=\"main-wrapper\">\n\n    <!-- Fluid Island Detached Navbar -->\n    <div class=\"nav-container\">\n      <nav class=\"fluid-island-nav\" aria-label=\"主导航\">\n        <a href=\"/\" class=\"nav-brand\">\n          <div class=\"brand-mark\">∑</div>\n          <div class=\"brand-title\">\n            高考全科知识库\n            <div class=\"status-badge\">\n              <div class=\"status-pulse\"></div>\n              <span>ONLINE</span>\n            </div>\n          </div>\n        </a>\n\n        <div class=\"nav-links\">\n          <a href=\"#subjects\" class=\"nav-link\">学科中枢</a>\n          <a href=\"#architecture\" class=\"nav-link\">系统架构</a>\n          <a href=\"https://yunet.cfd\" class=\"nav-link\" target=\"_blank\" rel=\"noopener\">关于主理人</a>\n        </div>\n\n        <div class=\"nav-actions\">\n          <button class=\"theme-button\" id=\"themeToggle\" aria-label=\"切换深色/浅色显示模式\" title=\"切换显示模式\">\n            <svg id=\"themeIconSun\" viewBox=\"0 0 24 24\">\n              <circle cx=\"12\" cy=\"12\" r=\"4\"/>\n              <path d=\"M12 2v2m0 16v2M4.93 4.93l1.41 1.41m11.32 11.32l1.41 1.41M2 12h2m16 0h2M6.34 17.66l-1.41 1.41m14.14-14.14l-1.41 1.41\"/>\n            </svg>\n          </button>\n        </div>\n      </nav>\n    </div>\n\n    <!-- Hero Section -->\n    <header class=\"hero-section reveal-element\">\n      <div class=\"eyebrow-tag\">\n        <span class=\"eyebrow-indicator\"></span>\n        FIRST-PRINCIPLES KNOWLEDGE NEXUS\n      </div>\n\n      <h1 class=\"hero-title\">\n        以第一性原理<br>\n        <span class=\"shimmer-text\">重构高考理科体系。</span>\n      </h1>\n\n      <p class=\"hero-subtitle\">\n        面向新高考深度备考的高精度系统知识中枢。彻底抛弃死记硬背与盲目题海，直击经典物理专题模型推演、全景生物调节机制通路与微观化学反应平衡。\n      </p>\n\n      <div class=\"hero-cta-group\">\n        <a href=\"https://physics.yunet.cfd\" class=\"island-btn island-btn-primary\">\n          <span>进入物理核心中枢</span>\n          <div class=\"btn-icon-wrapper\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M5 12h14m-6-6l6 6-6 6\"/></svg>\n          </div>\n        </a>\n        <a href=\"#subjects\" class=\"island-btn island-btn-secondary\">\n          <span>浏览全科矩阵</span>\n          <div class=\"btn-icon-wrapper\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M19 9l-7 7-7-7\"/></svg>\n          </div>\n        </a>\n      </div>\n\n      <!-- Live Specification / Metrics Strip -->\n      <div class=\"spec-strip\">\n        <div class=\"spec-item\">\n          <div class=\"spec-num\">19<span>+</span></div>\n          <div class=\"spec-label\">物理经典核心专题</div>\n        </div>\n        <div class=\"spec-item\">\n          <div class=\"spec-num\">5<span>卷</span></div>\n          <div class=\"spec-label\">生物全景教材脉络</div>\n        </div>\n        <div class=\"spec-item\">\n          <div class=\"spec-num\">100<span>%</span></div>\n          <div class=\"spec-label\">矢量几何拓扑推演</div>\n        </div>\n        <div class=\"spec-item\">\n          <div class=\"spec-num\">&lt;40<span>ms</span></div>\n          <div class=\"spec-label\">Anycast 全球秒级边缘响应</div>\n        </div>\n      </div>\n    </header>\n\n    <!-- Asymmetrical Bento Subjects Grid -->\n    <section id=\"subjects\" class=\"section-container\">\n      <div class=\"section-header-pill reveal-element\">\n        <div class=\"section-title-label\">FLAGSHIP SUBJECT PORTALS · 核心学科矩阵</div>\n        <div class=\"section-aux-info\">SYSTEM v2.6.4</div>\n      </div>\n\n      <div class=\"bento-grid\">\n        \n        <!-- Bento 1: Physics (Hero Anchor Card) -->\n        <a href=\"https://physics.yunet.cfd\" class=\"double-bezel bento-physics reveal-element\" target=\"_blank\" rel=\"noopener\">\n          <div class=\"inner-core\">\n            <div>\n              <div class=\"card-top\">\n                <div class=\"card-badge-row\">\n                  <span class=\"subject-pill-tag tag-phy\">PHYSICS 物理</span>\n                  <span class=\"card-domain-badge\">physics.yunet.cfd</span>\n                </div>\n                <div class=\"subject-icon-box\">\n                  <!-- Quantum Orbit Icon -->\n                  <svg viewBox=\"0 0 24 24\">\n                    <circle cx=\"12\" cy=\"12\" r=\"3\"/>\n                    <ellipse cx=\"12\" cy=\"12\" rx=\"9\" ry=\"3.8\" transform=\"rotate(-30 12 12)\"/>\n                    <ellipse cx=\"12\" cy=\"12\" rx=\"9\" ry=\"3.8\" transform=\"rotate(45 12 12)\"/>\n                  </svg>\n                </div>\n              </div>\n\n              <h2 class=\"card-headline\">高考物理知识库</h2>\n              <p class=\"card-desc\">\n                从开普勒双星变轨、粒子复合场偏转到电磁感应突变。采用微积分几何思维直击临界极值与守恒本质，构建全维力学与电磁学公理化演绎框架。\n              </p>\n\n              <div class=\"card-vector-preview\">\n                <span class=\"vector-label\">核心微模型群推导:</span>\n                <div class=\"vector-pill-cluster\">\n                  <span class=\"vector-pill\">开普勒轨道积分</span>\n                  <span class=\"vector-pill\">复合场回旋极限</span>\n                  <span class=\"vector-pill\">电磁阻尼感应微元</span>\n                  <span class=\"vector-pill\">等效重力场</span>\n                </div>\n              </div>\n            </div>\n\n            <div class=\"card-footer\">\n              <div class=\"card-tags\">\n                <span class=\"meta-tag\">19 核心专题</span>\n                <span class=\"meta-tag\">全矢量图解</span>\n                <span class=\"meta-tag\">微分几何解析</span>\n              </div>\n              <div class=\"card-cta-link\" aria-label=\"直达高考物理知识库\">\n                <span>开启物理推演</span>\n                <div class=\"cta-circle\">\n                  <svg viewBox=\"0 0 24 24\"><path d=\"M7 17L17 7M17 7H7M17 7V17\"/></svg>\n                </div>\n              </div>\n            </div>\n          </div>\n        </a>\n\n        <!-- Bento 2: Biology (Balanced Twin Left) -->\n        <a href=\"https://biology.yunet.cfd\" class=\"double-bezel bento-bio reveal-element\" target=\"_blank\" rel=\"noopener\">\n          <div class=\"inner-core\">\n            <div>\n              <div class=\"card-top\">\n                <div class=\"card-badge-row\">\n                  <span class=\"subject-pill-tag tag-bio\">BIOLOGY 生物</span>\n                  <span class=\"card-domain-badge\">biology.yunet.cfd</span>\n                </div>\n                <div class=\"subject-icon-box\">\n                  <!-- DNA Double Helix Arc Icon -->\n                  <svg viewBox=\"0 0 24 24\">\n                    <path d=\"M4 6c4 0 8 4 8 6s4 6 8 6\"/>\n                    <path d=\"M4 18c4 0 8-4 8-6s4-6 8-6\"/>\n                    <line x1=\"7\" y1=\"8\" x2=\"7\" y2=\"16\"/>\n                    <line x1=\"17\" y1=\"8\" x2=\"17\" y2=\"16\"/>\n                  </svg>\n                </div>\n              </div>\n\n              <h2 class=\"card-headline\">高考生物知识库</h2>\n              <p class=\"card-desc\">\n                全景贯通必修与选择性必修全五册教材。解构光合呼吸微观能量转移机理、神经体液免疫综合稳态通路与现代基因工程推演。\n              </p>\n\n              <div class=\"card-vector-preview\">\n                <span class=\"vector-label\">核心机制通路:</span>\n                <div class=\"vector-pill-cluster\">\n                  <span class=\"vector-pill\">光合电子传递链</span>\n                  <span class=\"vector-pill\">突触传递跨膜电位</span>\n                  <span class=\"vector-pill\">PCR 循环扩增</span>\n                </div>\n              </div>\n            </div>\n\n            <div class=\"card-footer\">\n              <div class=\"card-tags\">\n                <span class=\"meta-tag\">全五册系统图谱</span>\n                <span class=\"meta-tag\">稳态网络机制</span>\n              </div>\n              <div class=\"card-cta-link\" aria-label=\"直达高考生物知识库\">\n                <span>开启生物中枢</span>\n                <div class=\"cta-circle\">\n                  <svg viewBox=\"0 0 24 24\"><path d=\"M7 17L17 7M17 7H7M17 7V17\"/></svg>\n                </div>\n              </div>\n            </div>\n          </div>\n        </a>\n\n        <!-- Bento 3: Chemistry (Balanced Twin Right) -->\n        <a href=\"https://chemistry-note.seeridia.top\" class=\"double-bezel bento-chem reveal-element\" target=\"_blank\" rel=\"noopener\">\n          <div class=\"inner-core\">\n            <div>\n              <div class=\"card-top\">\n                <div class=\"card-badge-row\">\n                  <span class=\"subject-pill-tag tag-chem\">CHEMISTRY 化学</span>\n                  <span class=\"card-domain-badge\">chemistry-note.seeridia.top</span>\n                </div>\n                <div class=\"subject-icon-box\">\n                  <!-- Hexagonal Benzene / Molecular Lattice Icon -->\n                  <svg viewBox=\"0 0 24 24\">\n                    <polygon points=\"12 2 20.5 7 20.5 17 12 22 3.5 17 3.5 7\"/>\n                    <circle cx=\"12\" cy=\"12\" r=\"3.5\" stroke-dasharray=\"2 2\"/>\n                  </svg>\n                </div>\n              </div>\n\n              <h2 class=\"card-headline\">高考化学知识库</h2>\n              <p class=\"card-desc\">\n                深入微观电子排布与杂化轨道理论。剖析电化学电子转移、水溶液多重平衡移动、滴定突跃曲线及晶体晶胞空间投影。\n              </p>\n\n              <div class=\"card-vector-preview\">\n                <span class=\"vector-label\">微观反应推演:</span>\n                <div class=\"vector-pill-cluster\">\n                  <span class=\"vector-pill\">电极双电层电位</span>\n                  <span class=\"vector-pill\">多元弱酸分布系数</span>\n                  <span class=\"vector-pill\">面心立方坐标投影</span>\n                </div>\n              </div>\n            </div>\n\n            <div class=\"card-footer\">\n              <div class=\"card-tags\">\n                <span class=\"meta-tag\">微观杂化轨道</span>\n                <span class=\"meta-tag\">多重平衡移动</span>\n              </div>\n              <div class=\"card-cta-link\" aria-label=\"直达高考化学知识库\">\n                <span>开启化学中枢</span>\n                <div class=\"cta-circle\">\n                  <svg viewBox=\"0 0 24 24\"><path d=\"M7 17L17 7M17 7H7M17 7V17\"/></svg>\n                </div>\n              </div>\n            </div>\n          </div>\n        </a>\n\n      </div>\n    </section>\n\n    <!-- System Methodology & Architecture Section (4 Pillars) -->\n    <section id=\"architecture\" class=\"section-container\">\n      <div class=\"section-header-pill reveal-element\">\n        <div class=\"section-title-label\">SYSTEM METHODOLOGY · 知识库架构体系</div>\n        <div class=\"section-aux-info\">FOUNDATIONAL PRINCIPLES</div>\n      </div>\n\n      <div class=\"pillars-grid\">\n        <div class=\"pillar-card reveal-element\">\n          <div class=\"pillar-inner\">\n            <div class=\"pillar-header\">\n              <span class=\"pillar-number\">01 / AXIOMATIC</span>\n              <div class=\"pillar-icon-tiny\">\n                <svg viewBox=\"0 0 24 24\"><path d=\"M12 20h9M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z\"/></svg>\n              </div>\n            </div>\n            <h3 class=\"pillar-title\">公理化严谨推导</h3>\n            <p class=\"pillar-desc\">摒弃经验主义死背，每条物理守恒与微观平衡均从定义公理严格推导至临界状态。</p>\n          </div>\n        </div>\n\n        <div class=\"pillar-card reveal-element\">\n          <div class=\"pillar-inner\">\n            <div class=\"pillar-header\">\n              <span class=\"pillar-number\">02 / VECTOR SVG</span>\n              <div class=\"pillar-icon-tiny\">\n                <svg viewBox=\"0 0 24 24\"><polygon points=\"12 2 2 7 12 12 22 7 12 2\"/><polyline points=\"2 17 12 22 22 17\"/><polyline points=\"2 12 12 17 22 12\"/></svg>\n              </div>\n            </div>\n            <h3 class=\"pillar-title\">全保真矢量图解</h3>\n            <p class=\"pillar-desc\">采用工业级精确数学坐标系渲染 SVG 图示，无限放大保持锐利，空间场与受力关系纤毫毕现。</p>\n          </div>\n        </div>\n\n        <div class=\"pillar-card reveal-element\">\n          <div class=\"pillar-inner\">\n            <div class=\"pillar-header\">\n              <span class=\"pillar-number\">03 / ONTOLOGY</span>\n              <div class=\"pillar-icon-tiny\">\n                <svg viewBox=\"0 0 24 24\"><circle cx=\"18\" cy=\"5\" r=\"3\"/><circle cx=\"6\" cy=\"12\" r=\"3\"/><circle cx=\"18\" cy=\"19\" r=\"3\"/><line x1=\"8.59\" y1=\"13.51\" x2=\"15.42\" y2=\"17.49\"/><line x1=\"15.41\" y1=\"6.51\" x2=\"8.59\" y2=\"10.49\"/></svg>\n              </div>\n            </div>\n            <h3 class=\"pillar-title\">全景交叉知识图谱</h3>\n            <p class=\"pillar-desc\">打破教材单册局限，横向贯通必修与选择性必修，构建跨学科与跨模块多维关联网络。</p>\n          </div>\n        </div>\n\n        <div class=\"pillar-card reveal-element\">\n          <div class=\"pillar-inner\">\n            <div class=\"pillar-header\">\n              <span class=\"pillar-number\">04 / ANYCAST EDGE</span>\n              <div class=\"pillar-icon-tiny\">\n                <svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"2\" y1=\"12\" x2=\"22\" y2=\"12\"/><path d=\"M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z\"/></svg>\n              </div>\n            </div>\n            <h3 class=\"pillar-title\">全球边缘秒级直达</h3>\n            <p class=\"pillar-desc\">依托 Cloudflare 全球数百节点 Anycast 路由与极简静态架构，实现无等待极速加载响应。</p>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <!-- Editorial Minimalist Footer -->\n    <footer class=\"site-footer\">\n      <div class=\"footer-identity\">\n        <div class=\"footer-brand\">\n          <div class=\"brand-mark\" style=\"width: 24px; height: 24px; font-size: 11px;\">∑</div>\n          <span>高考全科知识库总中枢 · note.yunet.cfd</span>\n        </div>\n        <p class=\"footer-copy\">© 2026 Yulaoshizuikeai. Built for first-principles science learners.</p>\n      </div>\n\n      <nav class=\"footer-nav\" aria-label=\"底部链接\">\n        <a href=\"https://yunet.cfd\" class=\"footer-link\" target=\"_blank\" rel=\"noopener\">主理人首页</a>\n        <a href=\"https://physics.yunet.cfd\" class=\"footer-link\">物理专题</a>\n        <a href=\"https://biology.yunet.cfd\" class=\"footer-link\">生物网络</a>\n        <a href=\"https://chemistry-note.seeridia.top\" class=\"footer-link\">化学微观</a>\n      </nav>\n    </footer>\n\n  </div>\n\n  <!-- Micro-Interactions & Fluid Dynamics Controller -->\n  <script>\n    (function () {\n      'use strict';\n\n      // 1. Theme Management (Ethereal OLED Dark by Default, with System Fallback)\n      const themeToggle = document.getElementById('themeToggle');\n      const htmlEl = document.documentElement;\n\n      function getPreferredTheme() {\n        const stored = localStorage.getItem('site_theme');\n        if (stored) return stored;\n        return window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark';\n      }\n\n      function applyTheme(theme) {\n        htmlEl.setAttribute('data-theme', theme);\n        localStorage.setItem('site_theme', theme);\n      }\n\n      // Initialize\n      applyTheme(getPreferredTheme());\n\n      if (themeToggle) {\n        themeToggle.addEventListener('click', () => {\n          const current = htmlEl.getAttribute('data-theme') || 'dark';\n          const next = current === 'dark' ? 'light' : 'dark';\n          applyTheme(next);\n        });\n      }\n\n      // 2. High-Performance IntersectionObserver for Scroll Entrance\n      const revealItems = document.querySelectorAll('.reveal-element');\n      if ('IntersectionObserver' in window) {\n        const observer = new IntersectionObserver((entries, obs) => {\n          entries.forEach(entry => {\n            if (entry.isIntersecting) {\n              entry.target.classList.add('is-revealed');\n              obs.unobserve(entry.target);\n            }\n          });\n        }, {\n          threshold: 0.1,\n          rootMargin: '0px 0px -40px 0px'\n        });\n\n        revealItems.forEach(el => observer.observe(el));\n      } else {\n        revealItems.forEach(el => el.classList.add('is-revealed'));\n      }\n\n      // 3. Ambient Fluid Island Scroll Compression\n      const navIsland = document.querySelector('.fluid-island-nav');\n      if (navIsland) {\n        window.addEventListener('scroll', () => {\n          const scrollY = window.scrollY || window.pageYOffset;\n          if (scrollY > 50) {\n            navIsland.style.boxShadow = '0 16px 36px -6px rgba(0,0,0,0.3), inset 0 1px 1px rgba(255,255,255,0.15)';\n          } else {\n            navIsland.style.boxShadow = '0 12px 32px -8px rgba(0,0,0,0.18), inset 0 1px 1px rgba(255,255,255,0.12)';\n          }\n        }, { passive: true });\n      }\n    })();\n  </script>\n</body>\n</html>\n";
